function normalizePhone(o, cc) {
  if (!o.phone) return o;
  let p = String(o.phone);
  if (p.startsWith('0')) p = cc + p.slice(1);
  else if (!p.startsWith(cc) && p.length <= 10) p = cc + p;
  o.phone = p;
  return o;
}
const item = $input.first().json;
const body = (item.body && typeof item.body === 'object') ? item.body : item;
const countryCode = '{{CONFIG.phone_country_code}}';
let out = {
  action: 'new_booking', reply_kind: null, name: item.name || '', phone: '',
  service: item.service || '', requested_date: item.requested_date || '',
  requested_time: item.requested_time || '', notes: item.notes || '',
  raw_text: item.raw_text || item.text || '', source: 'whatsapp',
  button_reply_id: '', slot_index: null, booking_id: ''
};
if (body.name || body.phone) {
  out.source = body.source || 'web';
  out.name = body.name || '';
  out.phone = String(body.phone || '').replace(/[^0-9]/g, '');
  out.service = body.service || '';
  out.requested_date = body.date || '';
  out.requested_time = body.time || '';
  out.notes = body.notes || '';
  out.raw_text = '';
  return [{ json: normalizePhone(out, countryCode) }];
}
const value = body.entry && body.entry[0] && body.entry[0].changes &&
  body.entry[0].changes[0] && body.entry[0].changes[0].value;
if (value && value.messages && value.messages[0]) {
  const msg = value.messages[0];
  out.phone = String(msg.from || '').replace(/[^0-9]/g, '');
  const contacts = value.contacts || [];
  if (contacts[0] && contacts[0].profile) out.name = contacts[0].profile.name || '';
  const rawText = (msg.text && msg.text.body) ? msg.text.body : '';
  const button = (msg.interactive && msg.interactive.button_reply) ? msg.interactive.button_reply : null;
  if (button) {
    out.button_reply_id = button.id || '';
    const title = String(button.title || '').toLowerCase();
    const bid = button.id || '';
    if (bid.startsWith('SLOT_')) { out.action = 'slot_choice'; out.reply_kind = 'button'; }
    else if (bid === 'CANCEL' || title.indexOf('cancel') !== -1) { out.action = 'cancel'; }
    else if (bid === 'RESCHED' || title.indexOf('resched') !== -1) { out.action = 'reschedule'; }
  } else if (/^[1-9]$/.test(rawText.trim())) {
    out.action = 'slot_choice'; out.reply_kind = 'digit';
    out.slot_index = parseInt(rawText.trim(), 10) - 1;
    out.raw_text = rawText;
  } else {
    out.raw_text = rawText;
  }
  return [{ json: normalizePhone(out, countryCode) }];
}
out.source = 'email';
out.name = item.fromName || item.from || '';
out.raw_text = item.text || '';
return [{ json: normalizePhone(out, countryCode) }];

const item = $input.first().json;
if (item.requested_date && item.requested_time && item.service) {
  return [{ json: { ...item, parseable: true } }];
}
const services = {{CONFIG.services}};
const tz = '{{CONFIG.timezone}}';
const raw = String(item.raw_text || '').toLowerCase();
let service = '';
for (const s of Object.keys(services)) {
  if (raw.includes(s.toLowerCase())) { service = s; break; }
}
let dayOffset = null;
if (raw.includes('today')) dayOffset = 0;
else if (raw.includes('tomorrow')) dayOffset = 1;
else {
  const weekdayMap = { sunday: 7, monday: 1, tuesday: 2, wednesday: 3, thursday: 4, friday: 5, saturday: 6 };
  for (const wd of Object.keys(weekdayMap)) {
    if (raw.includes(wd)) {
      const now = DateTime.now().setZone(tz);
      let delta = weekdayMap[wd] - now.weekday;
      if (delta <= 0) delta += 7;
      dayOffset = delta;
      break;
    }
  }
}
const timeMatch = raw.match(/([0-9]{1,2})(?::([0-9]{2}))?[ ]*(am|pm)?/);
let requested_time = '';
if (timeMatch) {
  let h = parseInt(timeMatch[1], 10);
  const m = timeMatch[2] ? parseInt(timeMatch[2], 10) : 0;
  const mer = timeMatch[3] ? timeMatch[3].toLowerCase() : '';
  if (mer === 'pm' && h !== 12) h += 12;
  if (mer === 'am' && h === 12) h = 0;
  requested_time = String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
}
const parseable = dayOffset !== null && !!timeMatch && service !== '';
const now = DateTime.now().setZone(tz);
return [{ json: {
  ...item, service, requested_time,
  requested_date: parseable ? now.plus({ days: dayOffset }).toFormat('yyyy-MM-dd') : '',
  parseable
} }];

const item = $input.first().json;
const tz = '{{CONFIG.timezone}}';
const services = {{CONFIG.services}};
const businessHours = {{CONFIG.business_hours}};
const bookingIdPrefix = '{{CONFIG.booking_id_prefix}}';
const start = DateTime.fromISO(item.requested_date + 'T' + item.requested_time, { zone: tz });
const duration = (services[item.service] && services[item.service].duration_minutes) || 60;
const end = start.plus({ minutes: duration });
const open = String(businessHours.open || '09:00').split(':').map(Number);
const close = String(businessHours.close || '18:00').split(':').map(Number);
const days = businessHours.days || [1, 2, 3, 4, 5, 6, 7];
const startMinutes = start.hour * 60 + start.minute;
const dayOk = days.includes(start.weekday);
const valid = dayOk &&
  startMinutes >= open[0] * 60 + (open[1] || 0) &&
  startMinutes + duration <= close[0] * 60 + (close[1] || 0) &&
  start > DateTime.now().setZone(tz);
const phone = String(item.phone || '');
const booking_id = bookingIdPrefix + '-' + phone.slice(-4) + '-' + Math.floor(start.toMillis() / 1000);
return [{ json: {
  ...item,
  customer_name: item.name || '',
  booking_id,
  start_at: start.toISO(),
  end_at: end.toISO(),
  duration_minutes: duration,
  status: 'confirmed',
  context: 'new_booking',
  valid
} }];

const candidate = $('Resolve slot').first().json;
const rows = $input.all();
const windowMs = {{CONFIG.dedupe_window_minutes}} * 60000;
const dupes = rows.filter(r => {
  const j = r.json;
  if (j.booking_id === candidate.booking_id) return false;
  return j.phone === candidate.phone &&
    j.service === candidate.service &&
    Math.abs(Date.parse(j.start_at) - Date.parse(candidate.start_at)) < windowMs;
});
return [{ json: { ...candidate, duplicateCount: dupes.length } }];

