const item = $input.first().json;
const services = {{CONFIG.services}};
const id = String(item.button_reply_id || '');
const parts = id.split('_');
const ctx = parts[1] || 'alt';
const startAt = parts.slice(2, -1).join('_');
const bookingId = parts.slice(-1)[0] || '';
const contextMap = { alt: 'alternative', rec: 'recovery', res: 'reschedule' };
const context = contextMap[ctx] || 'alternative';
const service = item.service || '';
const duration = (services[service] && services[service].duration_minutes) || 60;
const end_at = DateTime.fromISO(startAt).plus({ minutes: duration }).toISO();
return [{ json: {
  ...item,
  context,
  start_at: startAt,
  end_at,
  booking_id: bookingId,
  customer_name: item.name || '',
  status: 'confirmed',
  source: item.source || 'whatsapp'
} }];

const item = $input.first().json;
const rows = $input.all();
const live = ['confirmed', 'reminded_24h', 'reminded', 'reminder_failed', 'no_show'];
const offers = rows
  .filter(r => r.json.phone === item.phone && r.json.pending_offer && live.includes(r.json.status))
  .sort((a, b) => Date.parse(b.json.created_at || 0) - Date.parse(a.json.created_at || 0));
if (!offers.length) {
  return [{ json: { ...item, resolved: false } }];
}
const row = offers[0].json;
const contextMap = { alt: 'alternative', rec: 'recovery', res: 'reschedule' };
return [{ json: {
  ...item,
  resolved: true,
  context: contextMap[row.pending_offer] || 'alternative',
  booking_id: row.booking_id,
  service: row.service,
  customer_name: row.customer_name,
  start_at: row.start_at,
  slot_index: item.slot_index
} }];

const ctx = $('Resolve digit context').first().json;
const services = {{CONFIG.services}};
const busy = ($json.busy || []).map(b => ({ s: Date.parse(b.start), e: Date.parse(b.end) }));
const step = {{CONFIG.slot_step_minutes}} * 60000;
const count = {{CONFIG.recovery_slot_count}};
const index = Number(ctx.slot_index || 0);
const base = Date.parse(ctx.start_at || new Date().toISOString());
const slots = [];
let t = base;
const limit = base + step * count * 2;
while (slots.length < count && t < limit) {
  if (!busy.some(b => t >= b.s && t < b.e)) slots.push(t);
  t += step;
}
const chosen = slots[index] || slots[0] || base;
const service = ctx.service || '';
const duration = (services[service] && services[service].duration_minutes) || 60;
return [{ json: {
  ...ctx,
  start_at: new Date(chosen).toISOString(),
  end_at: new Date(chosen + duration * 60000).toISOString(),
  booking_id: ctx.booking_id || '',
  slot_index: index
} }];

const item = $input.first().json;
const rows = $input.all();
const live = ['confirmed', 'reminded_24h', 'reminded', 'reminder_failed'];
const ordered = rows
  .filter(r => live.includes(r.json.status))
  .sort((a, b) => {
    const oa = live.indexOf(a.json.status);
    const ob = live.indexOf(b.json.status);
    if (oa !== ob) return oa - ob;
    return Date.parse(b.json.created_at || 0) - Date.parse(a.json.created_at || 0);
  });
if (!ordered.length) return [{ json: { ...item, active: false } }];
return [{ json: { ...ordered[0].json, active: true, phone: item.phone } }];

const rows = $input.all();
const newStart = $('Merge intake paths').first().json.start_at;
const live = ['confirmed', 'reminded_24h', 'reminded', 'reminder_failed'];
const old = rows
  .filter(r => r.json.start_at !== newStart && live.includes(r.json.status))
  .sort((a, b) => Date.parse(a.json.start_at) - Date.parse(b.json.start_at));
if (!old.length) return [];
return [{ json: old[0].json }];

const lead24 = {{CONFIG.reminder_lead_24h}};
const lead2 = {{CONFIG.reminder_lead_2h}};
const maxAttempts = {{CONFIG.max_reminder_attempts}};
const now = Date.now();
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const hours = (Date.parse(j.start_at) - now) / 3600000;
  if (hours <= 0 || hours > lead24) continue;
  const attempts = Number(j.reminder_attempts || 0);
  if (hours <= lead2) {
    if (['confirmed', 'reminded_24h', 'reminder_failed'].includes(j.status) && attempts < maxAttempts) {
      out.push({ json: { ...j, reminder_type: '2h' } });
    }
  } else {
    if (['confirmed', 'reminder_failed'].includes(j.status) && attempts < maxAttempts) {
      out.push({ json: { ...j, reminder_type: '24h' } });
    }
  }
}
return out;

const grace = {{CONFIG.no_show_grace_minutes}};
const now = Date.now();
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (Date.parse(j.start_at) + grace * 60000 <= now && ['confirmed', 'reminded_24h', 'reminded', 'reminder_failed'].includes(j.status)) {
    out.push(item);
  }
}
return out;
